1	// Public endpoints (no Clerk auth) for guests to view & cancel their booking.
2	// All actions are authorized purely by knowledge of the opaque, cryptographically
3	// random `management_token` that was generated when the guest's booking was created.
4	//
5	// Refund logic, money math, Stripe calls, idempotency keys, and email/notification
6	// side-effects mirror the authenticated DELETE /bookings/:id route exactly so guests
7	// and authed users get identical cancellation behavior.
8	
9	import { Router, type IRouter } from "express";
10	import { eq, and, ne } from "drizzle-orm";
11	import { db, bookingsTable, courtsTable, facilitiesTable } from "@workspace/db";
12	import { computeRefund, hoursBeforeStart } from "./bookings";
13	import { getUncachableStripeClient } from "../stripeClient";
14	import { logger } from "../lib/logger";
15	import { sendCustomerCancellationEmail, sendOwnerCancellationEmail } from "../lib/email";
16	import { sendNotification } from "../lib/notify";
17	import { timingSafeEqualToken, isPlausibleToken } from "../lib/guestToken";
18	
19	const router: IRouter = Router();
20	
21	function formatGuestBooking(
22	  booking: typeof bookingsTable.$inferSelect,
23	  court: { name?: string | null; address?: string | null; city?: string | null; phone?: string | null; imageUrl?: string | null; ownerEmail?: string | null } | null,
24	) {
25	  return {
26	    id: booking.id,
27	    courtId: booking.courtId,
28	    courtName: court?.name ?? undefined,
29	    courtAddress: court?.address ?? undefined,
30	    courtCity: court?.city ?? undefined,
31	    courtPhone: court?.phone ?? undefined,
32	    courtImageUrl: court?.imageUrl ?? undefined,
33	    customerName: booking.customerName,
34	    customerEmail: booking.customerEmail,
35	    customerPhone: booking.customerPhone ?? undefined,
36	    date: booking.date,
37	    startTime: booking.startTime,
38	    endTime: booking.endTime,
39	    totalPrice: Number(booking.totalPrice),
40	    status: booking.status,
41	    refundAmount: Number(booking.refundAmount ?? 0),
42	    rentedItems: booking.rentedItems ?? undefined,
43	    createdAt: booking.createdAt,
44	  };
45	}
46	
47	// ─── GET /api/guest/bookings/:token ──────────────────────────────────────────
48	// Fetches the booking + minimal court info, authorized solely by the token.
49	router.get("/guest/bookings/:token", async (req, res): Promise<void> => {
50	  const token = req.params.token;
51	  if (!isPlausibleToken(token)) {
52	    res.status(404).json({ error: "Booking not found" });
53	    return;
54	  }
55	
56	  const rows = await db
57	    .select({
58	      booking: bookingsTable,
59	      courtName: courtsTable.name,
60	      courtAddress: facilitiesTable.address,
61	      courtCity: facilitiesTable.city,
62	      courtPhone: courtsTable.phone,
63	      courtImageUrl: courtsTable.imageUrl,
64	    })
65	    .from(bookingsTable)
66	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
67	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
68	    .where(eq(bookingsTable.managementToken, token));
69	
70	  if (!rows[0]) {
71	    res.status(404).json({ error: "Booking not found" });
72	    return;
73	  }
74	
75	  const r = rows[0];
76	  res.json(formatGuestBooking(r.booking, {
77	    name: r.courtName,
78	    address: r.courtAddress,
79	    city: r.courtCity,
80	    phone: r.courtPhone,
81	    imageUrl: r.courtImageUrl,
82	  }));
83	});
84	
85	// ─── GET /api/guest/bookings/:token/refund-preview ───────────────────────────
86	// Mirrors GET /bookings/:id/refund-preview but token-authorized.
87	router.get("/guest/bookings/:token/refund-preview", async (req, res): Promise<void> => {
88	  const token = req.params.token;
89	  if (!isPlausibleToken(token)) {
90	    res.status(404).json({ error: "Booking not found" });
91	    return;
92	  }
93	
94	  const [booking] = await db
95	    .select()
96	    .from(bookingsTable)
97	    .where(eq(bookingsTable.managementToken, token));
98	
99	  if (!booking) {
100	    res.status(404).json({ error: "Booking not found" });
101	    return;
102	  }
103	
104	  const totalPriceEur = Number(booking.totalPrice);
105	  const hours = hoursBeforeStart(booking.date, booking.startTime);
106	  const tier = computeRefund(totalPriceEur, hours);
107	
108	  const canCancel = booking.status !== "cancelled" && hours > 0;
109	  let reason: string | undefined;
110	  if (booking.status === "cancelled") reason = "Booking is already cancelled.";
111	  else if (hours <= 0) reason = "Booking has already started or ended.";
112	
113	  res.json({
114	    bookingId: booking.id,
115	    totalPrice: totalPriceEur,
116	    hoursBeforeStart: Math.round(hours * 10) / 10,
117	    refundPercent: tier.refundPercent,
118	    refundAmount: tier.refundAmount,
119	    refundable: tier.refundable,
120	    canCancel,
121	    reason,
122	  });
123	});
124	
125	// ─── POST /api/guest/bookings/:token/cancel ──────────────────────────────────
126	// Mirrors DELETE /bookings/:id (atomic CAS + Stripe refund + emails) but
127	// authorized via the management token instead of a Clerk session.
128	router.post("/guest/bookings/:token/cancel", async (req, res): Promise<void> => {
129	  const token = req.params.token;
130	  if (!isPlausibleToken(token)) {
131	    res.status(404).json({ error: "Booking not found" });
132	    return;
133	  }
134	
135	  const rows = await db
136	    .select({
137	      booking: bookingsTable,
138	      courtName: courtsTable.name,
139	      courtOwnerUserId: facilitiesTable.ownerUserId,
140	      ownerName: facilitiesTable.name,
141	      ownerEmail: facilitiesTable.email,
142	    })
143	    .from(bookingsTable)
144	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
145	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
146	    .where(eq(bookingsTable.managementToken, token));
147	
148	  if (!rows[0]) {
149	    res.status(404).json({ error: "Booking not found" });
150	    return;
151	  }
152	
153	  const { booking, courtName, courtOwnerUserId, ownerName, ownerEmail } = rows[0];
154	
155	  // Idempotent: if it was already cancelled, just return current state.
156	  if (booking.status === "cancelled") {
157	    res.json({
158	      ...booking,
159	      totalPrice: Number(booking.totalPrice),
160	      refundAmount: Number(booking.refundAmount ?? 0),
161	    });
162	    return;
163	  }
164	
165	  const totalPriceEur = Number(booking.totalPrice);
166	  const hours = hoursBeforeStart(booking.date, booking.startTime);
167	  const tier = computeRefund(totalPriceEur, hours);
168	
169	  if (hours <= 0) {
170	    res.status(400).json({ error: "Booking has already started or ended", code: "CANCEL_TOO_LATE" });
171	    return;
172	  }
173	
174	  // Atomic compare-and-set on status to prevent double-refund races.
175	  const claimed = await db
176	    .update(bookingsTable)
177	    .set({ status: "cancelled" })
178	    .where(and(eq(bookingsTable.id, booking.id), ne(bookingsTable.status, "cancelled")))
179	    .returning();
180	
181	  if (claimed.length === 0) {
182	    const [current] = await db.select().from(bookingsTable).where(eq(bookingsTable.id, booking.id));
183	    res.json({
184	      ...current,
185	      totalPrice: Number(current.totalPrice),
186	      refundAmount: Number(current.refundAmount ?? 0),
187	    });
188	    return;
189	  }
190	
191	  let stripeRefundId: string | null = null;
192	  if (
193	    tier.refundable &&
194	    tier.refundAmount > 0 &&
195	    booking.stripePaymentIntentId &&
196	    !booking.stripePaymentIntentId.startsWith("mock_")
197	  ) {
198	    try {
199	      const stripe = await getUncachableStripeClient();
200	      const refund = await stripe.refunds.create(
201	        {
202	          payment_intent: booking.stripePaymentIntentId,
203	          amount: Math.round(tier.refundAmount * 100),
204	          reason: "requested_by_customer",
205	        },
206	        // Same idempotency key as the authed path so retries from any surface dedupe.
207	        { idempotencyKey: `cancel-booking-${booking.id}` },
208	      );
209	      stripeRefundId = refund.id;
210	      logger.info(
211	        { bookingId: booking.id, refundId: refund.id, amount: tier.refundAmount, source: "guest" },
212	        "Stripe refund issued (guest cancel)",
213	      );
214	    } catch (err) {
215	      logger.error({ err, bookingId: booking.id, source: "guest" }, "Stripe refund failed (guest cancel)");
216	      // Roll back the status transition so support can retry.
217	      await db
218	        .update(bookingsTable)
219	        .set({ status: booking.status })
220	        .where(eq(bookingsTable.id, booking.id));
221	      res.status(502).json({ error: "Refund failed at payment provider" });
222	      return;
223	    }
224	  }
225	
226	  const [cancelled] = await db
227	    .update(bookingsTable)
228	    .set({
229	      refundAmount: String(tier.refundAmount),
230	      stripeRefundId,
231	    })
232	    .where(eq(bookingsTable.id, booking.id))
233	    .returning();
234	
235	  // ─── Notifications (fire-and-forget) ─────────────────────────────────────
236	  const displayCourtName = courtName ?? "Kortas";
237	  const dateStr = String(booking.date);
238	
239	  if (courtOwnerUserId) {
240	    sendNotification(
241	      courtOwnerUserId,
242	      "booking_cancelled",
243	      `Atšaukta rezervacija — ${displayCourtName}`,
244	      `${booking.customerName} (svečias) atšaukė ${dateStr} ${booking.startTime}–${booking.endTime}.${
245	        tier.refundAmount > 0 ? ` Grąžinta klientui: ${tier.refundAmount.toFixed(2)} €.` : ""
246	      }`,
247	      "/owner",
248	    ).catch((err) => logger.error({ err, bookingId: booking.id }, "owner cancel notification failed (guest)"));
249	  }
250	
251	  if (booking.customerEmail) {
252	    sendCustomerCancellationEmail({
253	      customerName: booking.customerName,
254	      customerEmail: booking.customerEmail,
255	      courtName: displayCourtName,
256	      date: booking.date,
257	      startTime: booking.startTime,
258	      endTime: booking.endTime,
259	      totalPrice: totalPriceEur,
260	      refundAmount: tier.refundAmount,
261	      bookingId: booking.id,
262	    }).catch((err) => logger.error({ err, bookingId: booking.id }, "sendCustomerCancellationEmail failed (guest)"));
263	  }
264	
265	  if (ownerEmail) {
266	    sendOwnerCancellationEmail({
267	      ownerName: ownerName ?? "Savininkas",
268	      ownerEmail,
269	      customerName: booking.customerName,
270	      courtName: displayCourtName,
271	      date: booking.date,
272	      startTime: booking.startTime,
273	      endTime: booking.endTime,
274	      totalPrice: totalPriceEur,
275	      refundAmount: tier.refundAmount,
276	      bookingId: booking.id,
277	    }).catch((err) => logger.error({ err, bookingId: booking.id }, "sendOwnerCancellationEmail failed (guest)"));
278	  }
279	
280	  res.json({
281	    ...cancelled,
282	    totalPrice: Number(cancelled.totalPrice),
283	    refundAmount: Number(cancelled.refundAmount ?? 0),
284	    refundPercent: tier.refundPercent,
285	  });
286	});
287	
288	// ─── GET /api/guest/bookings/:token/ics ──────────────────────────────────────
289	// Public ICS download for guest bookings, mirrors GET /bookings/:id/ics.
290	router.get("/guest/bookings/:token/ics", async (req, res): Promise<void> => {
291	  const token = req.params.token;
292	  if (!isPlausibleToken(token)) {
293	    res.status(404).send("Booking not found");
294	    return;
295	  }
296	
297	  const rows = await db
298	    .select({
299	      booking: bookingsTable,
300	      courtName: courtsTable.name,
301	      courtId: courtsTable.id,
302	      courtAddress: facilitiesTable.address,
303	      courtCity: facilitiesTable.city,
304	    })
305	    .from(bookingsTable)
306	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
307	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
308	    .where(eq(bookingsTable.managementToken, token));
309	
310	  if (!rows[0]) {
311	    res.status(404).send("Booking not found");
312	    return;
313	  }
314	
315	  const { booking, courtName, courtId, courtAddress, courtCity } = rows[0];
316	  const siteUrl = process.env.SITE_URL || "https://korts.lt";
317	
318	  const icsDateTime = (date: string, time: string): string =>
319	    date.replace(/-/g, "") + "T" + time.slice(0, 5).replace(":", "") + "00";
320	
321	  const dtstamp = new Date().toISOString().replace(/[-:]/g, "").replace(/\.\d{3}/, "");
322	
323	  const ics = [
324	    "BEGIN:VCALENDAR",
325	    "VERSION:2.0",
326	    "PRODID:-//korts.lt//Court Booking//LT",
327	    "CALSCALE:GREGORIAN",
328	    "METHOD:PUBLISH",
329	    "BEGIN:VEVENT",
330	    `UID:booking-${booking.id}@korts.lt`,
331	    `DTSTAMP:${dtstamp}`,
332	    `DTSTART;TZID=Europe/Vilnius:${icsDateTime(booking.date, booking.startTime)}`,
333	    `DTEND;TZID=Europe/Vilnius:${icsDateTime(booking.date, booking.endTime)}`,
334	    `SUMMARY:Korto rezervacija – ${courtName ?? "Kortas"}`,
335	    `DESCRIPTION:Rezervacija #${booking.id} per korts.lt\\n${siteUrl}/courts/${courtId}`,
336	    `LOCATION:${courtAddress ?? ""}, ${courtCity ?? ""}, Lietuva`,
337	    `URL:${siteUrl}/courts/${courtId}`,
338	    "END:VEVENT",
339	    "END:VCALENDAR",
340	  ].join("\r\n");
341	
342	  res.setHeader("Content-Type", "text/calendar; charset=utf-8");
343	  res.setHeader("Content-Disposition", `attachment; filename="booking-${booking.id}.ics"`);
344	  res.send(ics);
345	});
346	
347	export default router;
348

